        if lhs.response != rhs.response {
            return false
        }
        if lhs.counterparty != rhs.counterparty {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(coin)
        hasher.combine(challenge)
        hasher.combine(response)
        hasher.combine(counterparty)
    }
}


